-- Textile POS — online server (MySQL 8 / MariaDB 10.5+) schema, migration 001.
-- Mirrors the logical model of the local SQLite database for synchronised entities.
-- IDs are the same UUIDv7 strings generated by the shop device (CHAR(36)); money in BIGINT paise; qty in BIGINT milli-units.
-- master_changes.id is a server-local AUTO_INCREMENT used only as a pull cursor, never as cross-device identity.

CREATE TABLE stores (
    id CHAR(36) NOT NULL PRIMARY KEY,
    code VARCHAR(20) NOT NULL,
    name VARCHAR(150) NOT NULL,
    created_at DATETIME NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE devices (
    id CHAR(36) NOT NULL PRIMARY KEY,
    store_id CHAR(36) NOT NULL,
    code VARCHAR(10) NOT NULL,
    name VARCHAR(100) NOT NULL,
    token_hash CHAR(64) NOT NULL,
    can_admin TINYINT NOT NULL DEFAULT 0,
    is_active TINYINT NOT NULL DEFAULT 1,
    last_seen_at DATETIME NULL,
    created_at DATETIME NOT NULL,
    CONSTRAINT fk_devices_store FOREIGN KEY (store_id) REFERENCES stores(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE UNIQUE INDEX ux_devices_token ON devices(token_hash);
CREATE UNIQUE INDEX ux_devices_store_code ON devices(store_id, code);

CREATE TABLE sync_receipts (
    event_id CHAR(36) NOT NULL PRIMARY KEY,
    store_id CHAR(36) NOT NULL,
    device_id CHAR(36) NOT NULL,
    entity_type VARCHAR(40) NOT NULL,
    entity_id CHAR(36) NOT NULL,
    op VARCHAR(30) NOT NULL,
    seq BIGINT NOT NULL,
    schema_version INT NOT NULL,
    status VARCHAR(20) NOT NULL,
    message VARCHAR(500) NULL,
    payload_hash CHAR(64) NOT NULL,
    payload LONGTEXT NOT NULL,
    event_created_at DATETIME NULL,
    received_at DATETIME NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX ix_receipts_device_seq ON sync_receipts(device_id, seq);
CREATE INDEX ix_receipts_entity ON sync_receipts(entity_type, entity_id);

CREATE TABLE customers (
    id CHAR(36) NOT NULL PRIMARY KEY,
    store_id CHAR(36) NOT NULL,
    name VARCHAR(100) NOT NULL,
    phone VARCHAR(15) NULL,
    email VARCHAR(150) NULL,
    gstin VARCHAR(15) NULL,
    address VARCHAR(500) NULL,
    state_code VARCHAR(4) NULL,
    is_active TINYINT NOT NULL DEFAULT 1,
    anonymized_at DATETIME NULL,
    origin_device_id CHAR(36) NULL,
    created_at DATETIME NOT NULL,
    updated_at DATETIME NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX ix_customers_phone ON customers(store_id, phone);

CREATE TABLE products (
    id CHAR(36) NOT NULL PRIMARY KEY,
    store_id CHAR(36) NOT NULL,
    code VARCHAR(30) NOT NULL,
    name VARCHAR(200) NOT NULL,
    category_name VARCHAR(100) NULL,
    brand_name VARCHAR(100) NULL,
    unit VARCHAR(5) NOT NULL,
    hsn_code VARCHAR(8) NULL,
    tax_code VARCHAR(30) NULL,
    status VARCHAR(10) NOT NULL,
    origin_device_id CHAR(36) NULL,
    updated_at DATETIME NOT NULL,
    server_updated_at DATETIME NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX ix_products_store_code ON products(store_id, code);

CREATE TABLE product_variants (
    id CHAR(36) NOT NULL PRIMARY KEY,
    product_id CHAR(36) NOT NULL,
    sku VARCHAR(40) NOT NULL,
    barcode VARCHAR(40) NOT NULL,
    size_label VARCHAR(30) NULL,
    color_name VARCHAR(40) NULL,
    design_no VARCHAR(40) NULL,
    mrp_paise BIGINT NOT NULL,
    price_paise BIGINT NOT NULL,
    cost_paise BIGINT NOT NULL DEFAULT 0,
    status VARCHAR(10) NOT NULL,
    admin_price_changed_at DATETIME NULL,
    updated_at DATETIME NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX ix_variants_product ON product_variants(product_id);
CREATE INDEX ix_variants_sku ON product_variants(sku);

CREATE TABLE tax_rules (
    code VARCHAR(30) NOT NULL PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    rate_bp INT NOT NULL,
    threshold_paise BIGINT NULL,
    above_rate_bp INT NULL,
    updated_at DATETIME NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE suppliers (
    id CHAR(36) NOT NULL PRIMARY KEY,
    store_id CHAR(36) NOT NULL,
    name VARCHAR(150) NOT NULL,
    gstin VARCHAR(15) NULL,
    phone VARCHAR(20) NULL,
    updated_at DATETIME NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE sales (
    id CHAR(36) NOT NULL PRIMARY KEY,
    store_id CHAR(36) NOT NULL,
    device_id CHAR(36) NOT NULL,
    invoice_no VARCHAR(30) NOT NULL,
    fy VARCHAR(8) NOT NULL,
    status VARCHAR(12) NOT NULL,
    sale_type VARCHAR(12) NOT NULL,
    customer_id CHAR(36) NULL,
    customer_name VARCHAR(100) NULL,
    customer_phone VARCHAR(15) NULL,
    customer_gstin VARCHAR(15) NULL,
    is_interstate TINYINT NOT NULL DEFAULT 0,
    cashier_id CHAR(36) NOT NULL,
    cashier_name VARCHAR(100) NULL,
    items_count INT NOT NULL,
    qty_total_milli BIGINT NOT NULL,
    gross_paise BIGINT NOT NULL,
    line_discount_paise BIGINT NOT NULL,
    bill_discount_paise BIGINT NOT NULL,
    taxable_paise BIGINT NOT NULL,
    cgst_paise BIGINT NOT NULL,
    sgst_paise BIGINT NOT NULL,
    igst_paise BIGINT NOT NULL,
    tax_paise BIGINT NOT NULL,
    round_off_paise BIGINT NOT NULL,
    total_paise BIGINT NOT NULL,
    paid_paise BIGINT NOT NULL,
    change_paise BIGINT NOT NULL,
    credit_paise BIGINT NOT NULL,
    cogs_paise BIGINT NOT NULL,
    created_at DATETIME NOT NULL,
    voided_at DATETIME NULL,
    void_reason VARCHAR(300) NULL,
    received_at DATETIME NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE UNIQUE INDEX ux_sales_invoice ON sales(store_id, invoice_no);
CREATE INDEX ix_sales_created ON sales(store_id, created_at);

CREATE TABLE sale_items (
    id CHAR(36) NOT NULL PRIMARY KEY,
    sale_id CHAR(36) NOT NULL,
    line_no INT NOT NULL,
    variant_id CHAR(36) NOT NULL,
    sku VARCHAR(40) NOT NULL,
    product_name VARCHAR(200) NOT NULL,
    variant_label VARCHAR(200) NULL,
    hsn_code VARCHAR(8) NULL,
    unit VARCHAR(5) NOT NULL,
    qty_milli BIGINT NOT NULL,
    unit_price_paise BIGINT NOT NULL,
    gross_paise BIGINT NOT NULL,
    line_discount_paise BIGINT NOT NULL,
    bill_discount_alloc_paise BIGINT NOT NULL,
    taxable_paise BIGINT NOT NULL,
    tax_rate_bp INT NOT NULL,
    cgst_paise BIGINT NOT NULL,
    sgst_paise BIGINT NOT NULL,
    igst_paise BIGINT NOT NULL,
    tax_paise BIGINT NOT NULL,
    line_total_paise BIGINT NOT NULL,
    cost_at_sale_paise BIGINT NOT NULL,
    cogs_paise BIGINT NOT NULL,
    CONSTRAINT fk_sale_items_sale FOREIGN KEY (sale_id) REFERENCES sales(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX ix_sale_items_sale ON sale_items(sale_id);
CREATE INDEX ix_sale_items_variant ON sale_items(variant_id);

CREATE TABLE payments (
    id CHAR(36) NOT NULL PRIMARY KEY,
    sale_id CHAR(36) NOT NULL,
    method VARCHAR(20) NOT NULL,
    amount_paise BIGINT NOT NULL,
    tendered_paise BIGINT NULL,
    change_paise BIGINT NOT NULL DEFAULT 0,
    reference VARCHAR(40) NULL,
    created_at DATETIME NOT NULL,
    CONSTRAINT fk_payments_sale FOREIGN KEY (sale_id) REFERENCES sales(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX ix_payments_sale ON payments(sale_id);

CREATE TABLE returns (
    id CHAR(36) NOT NULL PRIMARY KEY,
    store_id CHAR(36) NOT NULL,
    device_id CHAR(36) NOT NULL,
    return_no VARCHAR(30) NOT NULL,
    original_sale_id CHAR(36) NOT NULL,
    return_type VARCHAR(12) NOT NULL,
    reason VARCHAR(300) NULL,
    taxable_paise BIGINT NOT NULL,
    tax_paise BIGINT NOT NULL,
    total_paise BIGINT NOT NULL,
    round_off_paise BIGINT NOT NULL,
    refund_paise BIGINT NOT NULL,
    exchange_credit_paise BIGINT NOT NULL,
    cogs_reversed_paise BIGINT NOT NULL,
    created_at DATETIME NOT NULL,
    received_at DATETIME NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE UNIQUE INDEX ux_returns_no ON returns(store_id, return_no);

CREATE TABLE return_items (
    id CHAR(36) NOT NULL PRIMARY KEY,
    return_id CHAR(36) NOT NULL,
    sale_item_id CHAR(36) NOT NULL,
    variant_id CHAR(36) NOT NULL,
    qty_milli BIGINT NOT NULL,
    item_condition VARCHAR(10) NOT NULL,
    amount_paise BIGINT NOT NULL,
    taxable_paise BIGINT NOT NULL,
    tax_paise BIGINT NOT NULL,
    cogs_paise BIGINT NOT NULL,
    CONSTRAINT fk_return_items_return FOREIGN KEY (return_id) REFERENCES returns(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX ix_return_items_return ON return_items(return_id);

CREATE TABLE refunds (
    id CHAR(36) NOT NULL PRIMARY KEY,
    return_id CHAR(36) NOT NULL,
    method VARCHAR(20) NOT NULL,
    amount_paise BIGINT NOT NULL,
    reference VARCHAR(40) NULL,
    created_at DATETIME NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX ix_refunds_return ON refunds(return_id);

CREATE TABLE exchanges (
    id CHAR(36) NOT NULL PRIMARY KEY,
    return_id CHAR(36) NOT NULL,
    new_sale_id CHAR(36) NOT NULL,
    original_sale_id CHAR(36) NOT NULL,
    difference_paise BIGINT NOT NULL,
    created_at DATETIME NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE purchases (
    id CHAR(36) NOT NULL PRIMARY KEY,
    store_id CHAR(36) NOT NULL,
    device_id CHAR(36) NOT NULL,
    purchase_no VARCHAR(30) NOT NULL,
    supplier_id CHAR(36) NOT NULL,
    supplier_invoice_no VARCHAR(50) NULL,
    subtotal_paise BIGINT NOT NULL,
    tax_paise BIGINT NOT NULL,
    freight_paise BIGINT NOT NULL,
    total_paise BIGINT NOT NULL,
    amount_paid_paise BIGINT NOT NULL,
    posted_at DATETIME NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE purchase_items (
    id CHAR(36) NOT NULL PRIMARY KEY,
    purchase_id CHAR(36) NOT NULL,
    variant_id CHAR(36) NOT NULL,
    qty_milli BIGINT NOT NULL,
    unit_cost_paise BIGINT NOT NULL,
    landed_unit_cost_paise BIGINT NOT NULL,
    tax_paise BIGINT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX ix_purchase_items_purchase ON purchase_items(purchase_id);

CREATE TABLE stock_movements (
    id CHAR(36) NOT NULL PRIMARY KEY,
    store_id CHAR(36) NOT NULL,
    device_id CHAR(36) NOT NULL,
    variant_id CHAR(36) NOT NULL,
    location_code VARCHAR(10) NOT NULL,
    movement_type VARCHAR(20) NOT NULL,
    qty_milli BIGINT NOT NULL,
    unit_cost_paise BIGINT NOT NULL,
    value_paise BIGINT NOT NULL,
    ref_type VARCHAR(30) NULL,
    ref_id CHAR(36) NULL,
    created_at DATETIME NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX ix_server_movements_variant ON stock_movements(variant_id, created_at);

CREATE TABLE stock_balances (
    store_id CHAR(36) NOT NULL,
    variant_id CHAR(36) NOT NULL,
    location_code VARCHAR(10) NOT NULL,
    qty_milli BIGINT NOT NULL,
    updated_at DATETIME NOT NULL,
    PRIMARY KEY (store_id, variant_id, location_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE documents (
    id CHAR(36) NOT NULL PRIMARY KEY,
    store_id CHAR(36) NOT NULL,
    device_id CHAR(36) NOT NULL,
    doc_type VARCHAR(30) NOT NULL,
    doc_no VARCHAR(40) NULL,
    amount_paise BIGINT NULL,
    doc_date DATETIME NULL,
    payload LONGTEXT NOT NULL,
    received_at DATETIME NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX ix_documents_type ON documents(store_id, doc_type, doc_date);

CREATE TABLE conflicts (
    id CHAR(36) NOT NULL PRIMARY KEY,
    store_id CHAR(36) NOT NULL,
    device_id CHAR(36) NOT NULL,
    event_id CHAR(36) NULL,
    entity_type VARCHAR(40) NOT NULL,
    entity_id CHAR(36) NOT NULL,
    kind VARCHAR(40) NOT NULL,
    detail LONGTEXT NULL,
    status VARCHAR(12) NOT NULL DEFAULT 'open',
    created_at DATETIME NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX ix_conflicts_status ON conflicts(store_id, status);

CREATE TABLE master_changes (
    id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
    store_id CHAR(36) NOT NULL,
    origin_device_id CHAR(36) NULL,
    entity_type VARCHAR(40) NOT NULL,
    entity_id VARCHAR(40) NOT NULL,
    payload LONGTEXT NOT NULL,
    created_at DATETIME NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX ix_master_changes_store ON master_changes(store_id, id);

CREATE TABLE rate_limits (
    device_key VARCHAR(64) NOT NULL,
    window_start BIGINT NOT NULL,
    hits INT NOT NULL,
    PRIMARY KEY (device_key, window_start)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
